17	pub enum MemoryCommand {
18	    /// Create the memory database (it is also created on first write).
19	    Init,
20	    /// Store one memory. With --key, replaces that slot's current value.
21	    Remember {
22	        /// The claim, in a sentence.
23	        #[arg(required = true)]
24	        text: Vec<String>,
25	        #[arg(long, value_enum)]
26	        kind: Option<Kind>,
27	        /// Who or what it is about.
28	        #[arg(short, long)]
29	        subject: Option<String>,
30	        /// The slot that can change (editor, deploy.target, owner).
31	        #[arg(short, long)]
32	        key: Option<String>,
33	        #[arg(short, long = "tag")]
34	        tags: Vec<String>,
35	        /// 1 (trivia) to 5 (critical).
36	        #[arg(short, long)]
37	        importance: Option<u8>,
38	        #[arg(long)]
39	        confidence: Option<f64>,
40	        /// Where it came from (user, observed, a document).
41	        #[arg(long)]
42	        source: Option<String>,
43	        /// Related record id, path or URL (repeatable).
44	        #[arg(long = "ref")]
45	        refs: Vec<String>,
46	        /// Always lead briefings with it.
47	        #[arg(long)]
48	        pin: bool,
49	        /// A date, or a duration from now (12h, 30d, 6w).
50	        #[arg(long)]
51	        expires: Option<String>,
52	        /// Another name for the subject (repeatable).
53	        #[arg(long = "alias")]
54	        aliases: Vec<String>,
55	        #[arg(long)]
56	        ns: Option<String>,
57	    },
58	    /// Ranked memories within a token budget. No words: a briefing.
59	    Recall {
60	        words: Vec<String>,
61	        #[arg(short, long)]
62	        subject: Option<String>,
63	        /// Kinds, comma separated.
64	        #[arg(long, value_enum, value_delimiter = ',')]
65	        kind: Vec<Kind>,
66	        /// Namespaces, comma separated, or `*`.
67	        #[arg(long)]
68	        ns: Option<String>,
69	        #[arg(long)]
70	        since: Option<String>,
71	        #[arg(long)]
72	        until: Option<String>,
73	        /// What was true at the end of this date.
74	        #[arg(long)]
75	        as_of: Option<String>,
76	        /// Include superseded and forgotten memories.
77	        #[arg(long)]
78	        history: bool,
79	        /// Token budget.
80	        #[arg(short, long)]
81	        budget: Option<usize>,
82	        #[arg(short = 'n', long)]
83	        limit: Option<usize>,
84	        /// Also show the indexed records (--index) that memories reference.
85	        #[arg(long)]
86	        with_records: bool,
87	    },
88	    /// The session-start briefing, formatted for an agent's hook. Never fails the hook.
89	    Briefing {
90	        #[arg(long)]
91	        ns: Option<String>,
92	        #[arg(short, long)]
93	        budget: Option<usize>,
94	        #[arg(long, value_enum, default_value_t = BriefingFormat::Text)]
95	        format: BriefingFormat,
96	        /// Read the briefing from a remote Leviathan's MCP URL instead of a local file.
97	        #[arg(long, value_name = "URL")]
98	        remote: Option<String>,
99	        /// Bearer token file for --remote [default: the --token-env variable].
100	        #[arg(long, env = "LEVIATHAN_TOKEN_FILE", value_name = "FILE")]
101	        token_file: Option<PathBuf>,
102	        /// Environment variable holding the bearer token for --remote.
103	        #[arg(long, default_value = "LEVIATHAN_TOKEN", value_name = "NAME")]
104	        token_env: String,
105	    },
106	    /// Mark a memory as no longer true (kept as history until `prune`).
107	    Forget {
108	        id: Option<String>,
109	        #[arg(short, long)]
110	        subject: Option<String>,
111	        #[arg(short, long)]
112	        key: Option<String>,
113	        #[arg(long)]
114	        ns: Option<String>,
115	        #[arg(long)]
116	        reason: Option<String>,
117	    },
118	    /// Newest memories first.
119	    List {
120	        #[arg(long)]
121	        ns: Option<String>,
122	        #[arg(long, value_enum)]
123	        kind: Option<Kind>,
124	        #[arg(short, long)]
125	        subject: Option<String>,
126	        /// Include superseded, forgotten and expired.
