128	pub enum Kind {
129	    /// Something true about the world, a project or a person.
130	    Fact,
131	    /// How someone wants things done.
132	    Preference,
133	    /// A choice that was made, ideally with the reason.
134	    Decision,
135	    /// What was learned from a failure or a surprise.
136	    Lesson,
137	    /// Something that happened at a point in time.
138	    Event,
139	    /// Open work.
140	    Task,
141	    /// Anything else.
142	    Note,
143	}
144	
145	impl Kind {
146	    pub const ALL: [Kind; 7] =
147	        [Kind::Fact, Kind::Preference, Kind::Decision, Kind::Lesson, Kind::Event, Kind::Task, Kind::Note];
148	    pub const NAMES: &'static str = "fact, preference, decision, lesson, event, task, note";
149	
150	    pub fn as_str(self) -> &'static str {
151	        match self {
152	            Kind::Fact => "fact",
153	            Kind::Preference => "preference",
154	            Kind::Decision => "decision",
155	            Kind::Lesson => "lesson",
156	            Kind::Event => "event",
157	            Kind::Task => "task",
158	            Kind::Note => "note",
159	        }
160	    }
161	
162	    pub fn parse(value: &str) -> Option<Kind> {
163	        let v = value.trim().to_lowercase();
164	        Kind::ALL.into_iter().find(|k| k.as_str() == v || format!("{}s", k.as_str()) == v)
165	    }
166	
167	    /// Days until recency counts half; 0 means it does not decay. Facts,
168	    /// preferences, decisions and lessons stay true until superseded.
169	    fn default_half_life(self) -> f64 {
170	        match self {
171	            Kind::Event => 30.0,
172	            Kind::Task => 7.0,
173	            Kind::Note => 90.0,
174	            _ => 0.0,
175	        }
176	    }
177	}
