193	        let half_life = Kind::ALL
194	            .into_iter()
195	            .map(|k| {
196	                let days = cfg
197	                    .half_life
198	                    .iter()
199	                    .find(|(name, _)| Kind::parse(name) == Some(k))
200	                    .map_or(k.default_half_life(), |(_, d)| *d);
201	                (k, days)
202	            })
203	            .collect();
204	        let namespace = cfg.namespace.trim().to_lowercase();
205	        let read = if cfg.read.is_empty() {
206	            vec![namespace.clone()]
207	        } else {
