209	        };
210	        Self {
211	            namespace,
212	            read,
213	            budget: cfg.budget,
214	            briefing_budget: cfg.briefing_budget,
215	            max_chars: cfg.max_chars,
216	            pin: cfg.pin.clone(),
217	            half_life,
218	        }
219	    }
